      { text: 'ง. ออกแบบผังการจัดวางตู้เซิร์ฟเวอร์แบบ Hot-Cold Aisle เพื่อเพิ่มทิศทางไหลของอากาศ', weights: { art: 0.5, science: 0.3 } }
