    id: 'S304Q5', stageId: 304, title: 'การจัดทำคลังข้อมูลพันธุกรรมพืชสมุนไพรไทยแห่งชาติ',
    description: 'กระทรวงวิทยาศาสตร์ต้องการสร้างฐานข้อมูล DNA Barcoding พืชสมุนไพร 5,000 ชนิด คุณจะจัดการระบบข้อมูลอย่างไร?',
