    description: 'ฉากตัวละครเอกบอกลาเพื่อนสนิทดูราบเรียบเกินไปและสื่ออารมณ์เศร้าได้ไม่ถึงใจผู้ชม คุณจะปรับแก้สตอรี่บอร์ดอย่างไร?',
