export function getTargetLockQuestions(targetPath) {
  const clusterKey = TARGET_CLUSTERS[targetPath] || 'engineering';
  const themes = TARGETED_STAGE_THEMES[clusterKey] || [];
  const themeIds = themes.map(t => t.id);
  const questions = TARGETED_ASSESSMENT_BANK.filter(q => themeIds.includes(q.stageId));
  return {
    themes,
    questions
  };
}
